package auth

import (
	"bytes"
	"context"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"slices"
	"sort"
	"time"
)

// PreparedApprovalPlan comes ONLY from a trusted server task planner. The HTTP
// client supplies a plan reference, never this structure or a claimed digest.
// Digest must be the sole task service's canonical plan digest, not a different
// AI-only hash. ReviewSummary is generated by that fixed schema's redactor.
type PreparedApprovalPlan struct {
	ID, SubjectID, ActionID, Digest, Source, PluginID, AISessionID string
	AIScopeRevision                                                uint64
	NodeIDs                                                        []string
	RootShell                                                      bool
	ReviewSummary                                                  json.RawMessage
	ExpiresAt                                                      time.Time
}
type ApprovalPlanResolver func(context.Context, string) (PreparedApprovalPlan, error)

// PlanAdmission rechecks current AI scope/plugin/server restrictions. It is a
// read-only callback, also usable on the outer tasks Tx. Nil always fails closed.
type ApprovalPlanAdmission func(context.Context, PreparedApprovalPlan) error
type ApprovalView struct {
	ID            string          `json:"id"`
	PlanID        string          `json:"planId"`
	SubjectID     string          `json:"subjectId"`
	ActionID      string          `json:"actionId"`
	Digest        string          `json:"planDigest"`
	NodeIDs       []string        `json:"nodeIds"`
	Source        string          `json:"source"`
	State         string          `json:"state"`
	Revision      uint64          `json:"revision"`
	ExpiresAt     time.Time       `json:"expiresAt"`
	ReviewSummary json.RawMessage `json:"reviewSummary"`
}
type approvalRecord struct {
	View                         ApprovalView
	Plan                         PreparedApprovalPlan
	SubjectEpoch, PolicyRevision uint64
	ApproverID                   string
	ApproverEpoch                uint64
	HumanWeb, ApproverAdmin      bool
	ConsumedTaskID               string
}
type ApprovalService struct {
	identity *IdentityService
	plans    ApprovalPlanResolver
	admit    ApprovalPlanAdmission
	ttl      time.Duration
}

func NewApprovalService(identity *IdentityService, plans ApprovalPlanResolver, admit ApprovalPlanAdmission, ttl time.Duration) (*ApprovalService, error) {
	if identity == nil || plans == nil || admit == nil || ttl < time.Minute || ttl > 30*time.Minute {
		return nil, ErrIdentityUnavailable
	}
	return &ApprovalService{identity, plans, admit, ttl}, nil
}
func validPreparedPlan(plan PreparedApprovalPlan, now time.Time) bool {
	digest, err := hex.DecodeString(plan.Digest)
	if err != nil || len(digest) != 32 || hex.EncodeToString(digest) != plan.Digest || !validPolicyID(plan.ID) || len(plan.ID) > 128 || !validSecret(plan.SubjectID) || !validPolicyID(plan.ActionID) || len(plan.ActionID) > 128 || len(plan.NodeIDs) == 0 || len(plan.NodeIDs) > 200 || !validExactIDs(plan.NodeIDs) || len(plan.ReviewSummary) == 0 || len(plan.ReviewSummary) > 8<<10 || !json.Valid(plan.ReviewSummary) || bytes.Contains(plan.ReviewSummary, []byte("-----BEGIN")) || !now.Before(plan.ExpiresAt) || plan.ExpiresAt.Sub(now) > 15*time.Minute {
		return false
	}
	if plan.Source != "web" && plan.Source != "ai" && plan.Source != "plugin" && plan.Source != "system" {
		return false
	}
	if plan.Source == "ai" && (plan.AISessionID == "" || plan.AIScopeRevision == 0) {
		return false
	}
	if plan.Source == "plugin" && plan.PluginID == "" {
		return false
	}
	for _, id := range append(slices.Clone(plan.NodeIDs), plan.AISessionID, plan.PluginID) {
		if id != "" && (!validPolicyID(id) || len(id) > 128) {
			return false
		}
	}
	return true
}
func approvalView(record approvalRecord, now time.Time) ApprovalView {
	view := record.View
	view.NodeIDs = slices.Clone(view.NodeIDs)
	view.ReviewSummary = bytes.Clone(view.ReviewSummary)
	if (view.State == "pending" || view.State == "approved") && !now.Before(view.ExpiresAt) {
		view.State = "expired"
	}
	return view
}
func currentApprovalView(st *identityState, record approvalRecord, now time.Time) ApprovalView {
	view := approvalView(record, now)
	if view.State != "pending" && view.State != "approved" {
		return view
	}
	owner := st.Users[record.Plan.SubjectID]
	if owner.ID == "" || owner.Disabled || owner.Epoch != record.SubjectEpoch || record.PolicyRevision != st.PolicyRevision {
		view.State = "revoked"
		return view
	}
	if view.State == "approved" {
		user := st.Users[record.ApproverID]
		if user.ID == "" || user.Disabled || user.Epoch != record.ApproverEpoch || record.Plan.Source == "ai" && record.Plan.RootShell && !user.Administrator {
			view.State = "revoked"
		}
	}
	return view
}
func clonePreparedPlan(plan PreparedApprovalPlan) PreparedApprovalPlan {
	plan.NodeIDs = slices.Clone(plan.NodeIDs)
	sort.Strings(plan.NodeIDs)
	plan.ReviewSummary = bytes.Clone(plan.ReviewSummary)
	return plan
}
func (s *ApprovalService) planAllowed(ctx context.Context, st *identityState, plan PreparedApprovalPlan, subject string, now time.Time) error {
	user, ok := st.Users[subject]
	if !ok || user.Disabled {
		return ErrDenied
	}
	for _, action := range []string{plan.ActionID} {
		nodes, err := s.identity.grantedNodes(ctx, st, subject, action, now)
		if err != nil {
			return err
		}
		for _, node := range plan.NodeIDs {
			if _, ok := nodes[node]; !ok {
				return ErrDenied
			}
		}
	}
	if s.admit(ctx, clonePreparedPlan(plan)) != nil {
		return ErrDenied
	}
	return nil
}
func (s *ApprovalService) Request(ctx context.Context, secret, csrf, planID string) (ApprovalView, error) {
	if s == nil || s.identity == nil || s.plans == nil || s.admit == nil || ctx == nil || ctx.Err() != nil || !validPolicyID(planID) || len(planID) > 128 {
		return ApprovalView{}, ErrDenied
	}
	plan, err := s.plans(ctx, planID)
	if err != nil || plan.ID != planID {
		return ApprovalView{}, ErrIdentityUnavailable
	}
	plan = clonePreparedPlan(plan)
	var out ApprovalView
	err = s.identity.update(ctx, func(st *identityState, now time.Time) error {
		user, session, err := findIdentity(st, secret, now)
		if err != nil {
			return err
		}
		if !matchCSRF(csrf, session.CSRF) {
			return ErrDenied
		}
		if plan.SubjectID != user.ID || !validPreparedPlan(plan, now) {
			return ErrDenied
		}
		if err = s.planAllowed(ctx, st, plan, user.ID, now); err != nil {
			return err
		}
		for _, record := range st.Approvals {
			if record.Plan.ID == plan.ID && record.Plan.SubjectID == user.ID {
				if requestDigest(record.Plan) != requestDigest(plan) {
					return ErrRevisionConflict
				}
				out = currentApprovalView(st, record, now)
				return nil
			}
		}
		if len(st.Approvals) >= 10000 {
			return ErrIdentityUnavailable
		}
		id, err := randomIdentity(s.identity.random)
		if err != nil {
			return err
		}
		expires := now.Add(s.ttl)
		if plan.ExpiresAt.Before(expires) {
			expires = plan.ExpiresAt
		}
		view := ApprovalView{id, plan.ID, user.ID, plan.ActionID, plan.Digest, slices.Clone(plan.NodeIDs), plan.Source, "pending", 1, expires, bytes.Clone(plan.ReviewSummary)}
		record := approvalRecord{View: view, Plan: plan, SubjectEpoch: user.Epoch, PolicyRevision: st.PolicyRevision}
		st.Approvals[id] = record
		out = approvalView(record, now)
		return appendIdentityAudit(st, user.ID, "auth.approval.request", "succeeded", now, plan.NodeIDs...)
	})
	if err != nil {
		return ApprovalView{}, err
	}
	return out, nil
}
func matchCSRF(csrf, expected string) bool {
	return validSecret(csrf) && validSecret(expected) && subtleTokenEqual(csrf, expected)
}

// Separate helper keeps the comparison constant-time without treating CSRF as
// a session credential or accepting a management ID as an authentication proof.
func subtleTokenEqual(a, b string) bool { return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1 }
func (s *ApprovalService) Get(ctx context.Context, secret, id string) (ApprovalView, error) {
	var out ApprovalView
	if s == nil || s.identity == nil || s.admit == nil {
		return out, ErrIdentityUnavailable
	}
	err := s.identity.update(ctx, func(st *identityState, now time.Time) error {
		user, _, err := findIdentity(st, secret, now)
		if err != nil {
			return err
		}
		record, ok := st.Approvals[id]
		if !ok {
			return ErrDenied
		}
		if err = s.planAllowed(ctx, st, record.Plan, user.ID, now); err != nil {
			return err
		}
		if record.Plan.SubjectID != user.ID {
			grants, err := s.identity.grantedNodes(ctx, st, user.ID, "tasks.approve", now)
			if err != nil {
				return err
			}
			for _, node := range record.Plan.NodeIDs {
				if _, ok := grants[node]; !ok {
					return ErrDenied
				}
			}
			if record.Plan.Source == "ai" && record.Plan.RootShell && !user.Administrator {
				return ErrDenied
			}
		}
		out = currentApprovalView(st, record, now)
		return nil
	})
	if err != nil {
		return ApprovalView{}, err
	}
	return out, nil
}

// Decide is called only by the trusted Web composition after strict TLS Origin
// and CSRF authentication. There is deliberately no AI/Host decision port.
func (s *ApprovalService) Decide(ctx context.Context, secret, csrf, id string, expected uint64, approve bool) (ApprovalView, error) {
	var out ApprovalView
	if s == nil || s.identity == nil || s.admit == nil {
		return out, ErrIdentityUnavailable
	}
	var outcome error
	err := s.identity.update(ctx, func(st *identityState, now time.Time) error {
		user, session, err := findIdentity(st, secret, now)
		if err != nil {
			return err
		}
		if !matchCSRF(csrf, session.CSRF) {
			return ErrDenied
		}
		record, ok := st.Approvals[id]
		if !ok || record.View.State != "pending" {
			return ErrDenied
		}
		if expected == 0 || record.View.Revision != expected {
			return ErrRevisionConflict
		}
		if !now.Before(record.View.ExpiresAt) {
			record.View.State = "expired"
			record.View.Revision++
			st.Approvals[id] = record
			outcome = ErrDenied
			return nil
		}
		owner := st.Users[record.Plan.SubjectID]
		if owner.Disabled || owner.Epoch != record.SubjectEpoch || record.PolicyRevision != st.PolicyRevision {
			return ErrDenied
		}
		if err = s.planAllowed(ctx, st, record.Plan, owner.ID, now); err != nil {
			return err
		}
		// Approving requires current action permission AND explicit approve grants.
		if err = s.planAllowed(ctx, st, record.Plan, user.ID, now); err != nil {
			return err
		}
		nodes, err := s.identity.grantedNodes(ctx, st, user.ID, "tasks.approve", now)
		if err != nil {
			return err
		}
		for _, node := range record.Plan.NodeIDs {
			if _, ok := nodes[node]; !ok {
				return ErrDenied
			}
		}
		if record.Plan.Source == "ai" && record.Plan.RootShell && !user.Administrator {
			return ErrDenied
		}
		record.View.State = "denied"
		if approve {
			record.View.State = "approved"
		}
		record.View.Revision++
		record.ApproverID = user.ID
		record.ApproverEpoch = user.Epoch
		record.HumanWeb = true
		record.ApproverAdmin = user.Administrator
		st.Approvals[id] = record
		out = approvalView(record, now)
		action := "auth.approval.deny"
		if approve {
			action = "auth.approval.approve"
		}
		return appendIdentityAudit(st, user.ID, action, "succeeded", now, record.Plan.NodeIDs...)
	})
	if err != nil {
		return ApprovalView{}, err
	}
	if outcome != nil {
		return ApprovalView{}, outcome
	}
	return out, nil
}

// ConsumeTx is adapted to the DS ApprovalConsumer using its SAME Tx. This
// function never begins/commits an outer transaction or sends output. The caller
// must roll it back if task insertion/audit fails. No standalone consume method.
type ApprovalTaskBinding struct {
	TaskID, SubjectID, ActionID, Digest, Source, PluginID, AISessionID string
	AIScopeRevision                                                    uint64
	NodeIDs                                                            []string
}

func (s *ApprovalService) ConsumeTx(ctx context.Context, tx IdentitySQLStatements, id string, binding ApprovalTaskBinding) (string, error) {
	if s == nil || s.identity == nil || s.admit == nil || ctx == nil || tx.Read == nil || tx.Exec == nil || !validSecret(id) || !validSecret(binding.SubjectID) || !validExactIDs(binding.NodeIDs) || !validPolicyID(binding.TaskID) || len(binding.TaskID) > 128 {
		return "", ErrDenied
	}
	store, err := NewSQLIdentityStore(IdentitySQLBackend{Read: tx.Read, InTx: func(ctx context.Context, fn func(IdentitySQLStatements) error) error { return fn(tx) }})
	if err != nil {
		return "", err
	}
	boundIdentity := *s.identity
	boundIdentity.store = store
	bound := *s
	bound.identity = &boundIdentity
	var approver string
	var outcome error
	err = bound.identity.update(ctx, func(st *identityState, now time.Time) error {
		record, ok := st.Approvals[id]
		nodes := slices.Clone(binding.NodeIDs)
		sort.Strings(nodes)
		if !ok || record.View.State != "approved" || record.Plan.SubjectID != binding.SubjectID || record.Plan.Digest != binding.Digest || record.Plan.ActionID != binding.ActionID || record.Plan.Source != binding.Source || record.Plan.PluginID != binding.PluginID || record.Plan.AISessionID != binding.AISessionID || record.Plan.AIScopeRevision != binding.AIScopeRevision || !slices.Equal(record.Plan.NodeIDs, nodes) || !record.HumanWeb {
			return ErrDenied
		}
		if !now.Before(record.View.ExpiresAt) {
			outcome = ErrDenied
			return nil
		}
		owner, decider := st.Users[binding.SubjectID], st.Users[record.ApproverID]
		if owner.ID == "" || decider.ID == "" || owner.Disabled || decider.Disabled || owner.Epoch != record.SubjectEpoch || decider.Epoch != record.ApproverEpoch || record.PolicyRevision != st.PolicyRevision {
			return ErrDenied
		}
		if record.Plan.Source == "ai" && record.Plan.RootShell && (!record.ApproverAdmin || !decider.Administrator) {
			return ErrDenied
		}
		if err := bound.planAllowed(ctx, st, record.Plan, binding.SubjectID, now); err != nil {
			return err
		}
		if err := bound.planAllowed(ctx, st, record.Plan, decider.ID, now); err != nil {
			return err
		}
		grants, err := bound.identity.grantedNodes(ctx, st, decider.ID, "tasks.approve", now)
		if err != nil {
			return err
		}
		for _, node := range nodes {
			if _, ok := grants[node]; !ok {
				return ErrDenied
			}
		}
		record.View.State = "consumed"
		record.View.Revision++
		record.ConsumedTaskID = binding.TaskID
		st.Approvals[id] = record
		approver = record.ApproverID
		return appendIdentityAudit(st, decider.ID, "auth.approval.consume", "succeeded", now, nodes...)
	})
	if err != nil {
		return "", err
	}
	if outcome != nil {
		return "", outcome
	}
	return approver, nil
}
